/// Absolute paths: POSIX (`/…`), home (`~…`), Windows drive (`C:…`), or UNC (`\\…`).
/// Mirrors `isAbsolute` in `fsConfine.ts`.
pub(crate) fn is_absolute(p: &str) -> bool {
    p.starts_with('/')
        || p.starts_with('~')
        || p.starts_with("\\\\")
        || (p.len() >= 2 && p.as_bytes()[0].is_ascii_alphabetic() && p.as_bytes()[1] == b':')
}
